def sha(raw): return hashlib.sha256(raw).hexdigest()


@contextmanager
def generated(op):
    with tempfile.TemporaryDirectory() as td, ExitStack() as stack:
        root=Path(td); repo=root/'repo'; (repo/'tools').mkdir(parents=True)
        public=repo/'docs/evidence/poc-asr-001'; public.mkdir(parents=True)
        acceptance=root/'acceptance'; materialized=acceptance/'materialized-5.6c11'
        runtime=root/'runtime'; (runtime/'examples').mkdir(parents=True)
        model=root/'ggml-small-q5_1.bin'; model.write_bytes(b'generated-small-model')
        (runtime/'examples/miniaudio.h').write_bytes(b'generated decoder')
        (runtime/'samples').mkdir(); (runtime/'samples/jfk.mp3').write_bytes(b'generated codec')
        native=root/'native'; native.mkdir()
        native_pins={}; native_paths={}
        for name in op.NATIVE_NAMES:
            p=native/name; p.write_bytes(('generated '+name).encode())
            native_pins[name]={'bytes':p.stat().st_size,'sha256':sha(p.read_bytes())}; native_paths[name]=str(p)
        decoding={'resolvedWhisperFullParams':{'ru':{'language':'ru'},'en':{'language':'en'}},'generatedFloat':0.5}
        protocol={'decoderSha256':sha(b'generated decoder')}; gates={'generated':'gates'}
        for name,value in [('alpha-asr-decoding-profile-stage0-v0.1.json',decoding),
                           ('alpha-asr-measurement-protocol-stage0-v0.1.json',protocol),
                           ('alpha-asr-small-evaluation-governance-stage0-v0.1.json',{'resourceGates':gates}),
                           ('alpha-asr-campaign-stage0-v0.1.json',{'runtime':{'nativeArtifacts':native_pins},'generatedFloat':0.5})]:
            (public/name).write_bytes(c.canonical(value))
        stack.enter_context(patch.multiple(c,MODEL_BYTES=model.stat().st_size,MODEL_SHA=sha(model.read_bytes()),
            DECODING_SHA=c.digest(decoding),PROTOCOL_SHA=c.digest(protocol),GATES_SHA=c.digest(gates)))
        docs=fixture()
        for i,(row,b) in enumerate(zip(docs[0]['samples'],docs[1]['bindings'])):
            audio=f'generated audio {i}'.encode(); reference=f'generated reference {i}'.encode()
            for kind,raw in [('audio',audio),('reference',reference)]:
                p=materialized/b[kind+'RelativePath']; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(raw)
                b[kind+'Bytes']=len(raw); b[kind+'Sha256']=sha(raw)
            row.update(audioByteLength=len(audio),audioSha256=sha(audio),referenceTextSha256=sha(reference))
        refresh(docs,rebuild_transfer=True)
        for relative,value in zip(v2.METADATA_PATHS,docs):
            p=acceptance/relative; p.parent.mkdir(parents=True,exist_ok=True); p.write_bytes(c.canonical(value)+b'\n')
        stack.enter_context(patch.object(v2,'DOCUMENT_PINS',pins(docs)))
        stack.enter_context(patch.object(op,'__file__',str(repo/'tools/run_alpha_asr_small_campaign_v3.py')))
        stack.enter_context(patch.object(op,'verify_repository'))
        stack.enter_context(patch.object(op,'require_private'))
        stack.enter_context(patch.object(op,'require_model_storage'))
        stack.enter_context(patch.object(op.datetime,'date',AdmittedDate))
        def git(args,**kwargs):
            return subprocess.CompletedProcess(args,0,c.text.RUNTIME_COMMIT.encode() if args[-1]=='HEAD' else b'',b'')
        stack.enter_context(patch.object(op.subprocess,'run',side_effect=git))
        config=dict(operatorCommit='a'*40,acceptance=str(acceptance),work=str(root/'work'),model=str(model),
                    native=native_paths,runtimeSource=str(runtime),adb='GENERATED_ADB_NEVER_EXECUTED')
        yield SimpleNamespace(config=config,repo=repo,root=root,docs=docs,decoding=decoding,public=public)


class FakeOracle:
    instances=[]
    def __init__(self,path): self.scores=[]; self.instances.append(self)
    def compile(self): pass
    def score(self,prepared):
        self.scores.append(prepared['caseId'])
        return {k:dict(substitutions=0,deletions=0,insertions=0,referenceTokens=100) for k in ('raw','normalized')}


class FakeDevice:
    instances=[]
    failure=None
    def __init__(self,*args):
        self.calls=[]; self.cleanup_calls=0; self.connected=0; self.instances.append(self)
    def connect(self): self.connected+=1; return {'thermalStatus':0}
    def prepare(self): pass
    def profile(self,locale): return {'language':locale}
    def execute(self,audio,locale,destination,mode='infer'):
        destination=Path(destination); name=destination.name
        self.calls.append((name,mode,locale))
        destination.mkdir(parents=True,exist_ok=False)
        corpus=name.isdigit(); frames=16000
        if name=='warmup':
            with wave.open(str(audio),'rb') as sound:
                assert sound.getnframes()==48000 and sound.getframerate()==16000
                assert sound.getnchannels()==1 and sound.getsampwidth()==2
                assert sound.readframes(48000)==b'\0'*96000
            frames=48000
        if corpus:
            with closing(sqlite3.connect(destination.parents[1]/'attempts.sqlite')) as db:
                rows=db.execute('SELECT id,ordinal,state FROM attempts ORDER BY id').fetchall()
            assert rows[-1]==(int(name),1,'RUNNING'), 'Journal must precede backend'
        metrics=dict(nativeCode=0,decodedFrames=frames,sampleRate=16000,inferenceElapsedMicros=1000000,
                     modelLoadElapsedMicros=100000,measurementStartMicros=1000000,measurementEndMicros=2000000)
        (destination/'metrics.json').write_bytes(c.canonical(metrics))
        (destination/'memory.csv').write_text('1000000,1000,1000\n2000000,1000,1000\n')
        (destination/'thermal.jsonl').write_text('{"monotonicSeconds":1,"status":0}\n{"monotonicSeconds":2,"status":0}\n')
        (destination/'cleanup.json').write_text('{"status":"VERIFIED"}')
        (destination/'hypothesis.txt').write_text('generated hypothesis')
        if self.failure=='invalid' and corpus: (destination/'memory.csv').write_text('invalid')
        if self.failure=='partial' and corpus:
            (destination/'thermal.jsonl').write_text('{"monotonicSeconds":1,"status":3}\n')
            raise ValueError('GENERATED_BACKEND_FAILURE')
        if self.failure=='ambiguous' and corpus: raise ValueError('GENERATED_BACKEND_FAILURE')
        if self.failure=='warmup' and name=='warmup': raise ValueError('GENERATED_WARMUP_FAILURE')
        return {'metrics':metrics,'thermal':{'maximum':0}}
    def cleanup(self): self.cleanup_calls+=1; return 'VERIFIED'


class ExecutionSuccessorTests(unittest.TestCase):
    def setUp(self):
        self.assertIsNotNone(importlib.util.find_spec('run_alpha_asr_small_campaign_v3'), 'Execution successor is not implemented')
        import run_alpha_asr_small_campaign_v3 as op
        self.op=op; FakeDevice.instances=[]; FakeOracle.instances=[]; FakeDevice.failure=None

    @contextmanager
    def campaign_fixture(self):
        with generated(self.op) as env,patch.object(self.op,'Device',FakeDevice),patch.object(self.op,'Oracle',FakeOracle), \
             patch.object(v1,'verify_inputs',side_effect=AssertionError('Broken v1 verifier')), \
             patch.object(v1,'campaign',side_effect=AssertionError('Historical campaign')):
            yield env

    def test_exact_v2_composition_and_derived_48_bindings(self):
        with generated(self.op) as env,patch.object(v2,'bind_metadata',wraps=v2.bind_metadata) as binder:
            result=self.op.verify_inputs(env.config)
            self.assertEqual(1,binder.call_count)
            self.assertEqual(env.docs[0]['samples'],result.rows)
            self.assertEqual(48,len(result.cases))
            for row,b in zip(result.rows,env.docs[1]['bindings']):
                case=result.cases[row['sampleId']]
                self.assertEqual(Path(env.config['acceptance'])/'materialized-5.6c11'/b['audioRelativePath'],case.audio)
                self.assertEqual(Path(env.config['acceptance'])/'materialized-5.6c11'/b['referenceRelativePath'],case.reference)

    def test_config_bindings_unknown_keys_rejected_before_reads(self):
        for key in ('bindings','selectionSha256','modelSha256','operatorId','unknown'):
            with self.subTest(key=key),patch.object(Path,'read_bytes',side_effect=AssertionError('No reads')):
                with self.assertRaisesRegex(ValueError,'CONFIG'):
                    self.op.verify_inputs({key:{}})

    def test_wrong_missing_old_authorization_before_paths(self):
        for token in (None,'','OWNER_AUTHORIZED_5.6C.2B','OWNER_AUTHORIZED_5.6C.2A.2'):
            with self.subTest(token=token),patch.object(Path,'read_bytes',side_effect=AssertionError('No reads')), \
                 patch.object(self.op,'verify_inputs',side_effect=AssertionError('No precheck')), \
                 self.assertRaisesRegex(ValueError,'NOT_AUTHORIZED'):
                self.op.campaign({},token)

    def test_cli_is_information_only(self):
        with patch.object(Path,'read_bytes',side_effect=AssertionError('No reads')),redirect_stdout(io.StringIO()) as output:
            self.assertEqual(2,self.op.main(['campaign','private-path']))
        self.assertNotIn('private-path',output.getvalue())

