                    p=Path(env.config['acceptance'])/'materialized-5.6c11'/env.docs[1]['bindings'][0][kind+'RelativePath']
                    raw=p.read_bytes(); p.write_bytes(b'x'*(len(raw)+(mutation=='size')))
